<script setup lang="ts">
import { uiText, uiLocale } from '@/i18n'

import { ref,onMounted,onBeforeUnmount,watch } from 'vue'
import { request } from '@/api/client'
import { personalApi } from '@/api/personal'
import { authStore } from '@/stores/auth'
import type { TrainingJob } from '@/types/personal'
interface Job {id:string;kind:string;title:string;status:string;progress:number;attempts:number;resultId?:string;message?:string;createdAt:string}
const status=ref('ALL')
const rows=ref<Job[]>([]),training=ref<TrainingJob[]>([]),page=ref(0),busy=ref(''),error=ref(''),trainingError=ref(''),loading=ref(false),controller=new AbortController();let timer:ReturnType<typeof setTimeout>,loadEpoch=0
const names:Record<string,string>={QUEUED:'排队中',RUNNING:'处理中',CANCELLING:'正在取消',CANCELLED:'已取消',SUCCEEDED:'已完成',COMPLETED:'已完成',FAILED:'未完成'}
async function load(){if(controller.signal.aborted)return;const version=++loadEpoch;loading.value=true;error.value='';try{const result=await request<Job[]>('/workspace-jobs?page='+page.value+'&status='+status.value,{signal:controller.signal});if(!controller.signal.aborted&&version===loadEpoch)rows.value=result}catch(e){if(!controller.signal.aborted&&version===loadEpoch){rows.value=[];error.value=(e as Error).message}}finally{if(version===loadEpoch)loading.value=false}}
async function loadTraining(){if(!authStore.has('training:use'))return;try{const result=await personalApi.trainingJobs();if(!controller.signal.aborted){training.value=result;trainingError.value=''}}catch{if(!controller.signal.aborted)trainingError.value='训练环境暂时未连接，其他任务不受影响'}}
async function action(j:Job,action:string){if(busy.value)return;busy.value=j.id;try{await request(`/workspace-jobs/${j.id}/${action}`,{method:'POST'});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function remove(j:Job){if(busy.value||!confirm(uiText('移除这条任务记录？已完成的文档会保留；失败任务的暂存文件会清理。')))return;busy.value=j.id;try{await request('/workspace-jobs/'+j.id,{method:'DELETE'});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function cancelTraining(id:string){if(busy.value)return;busy.value=id;try{await personalApi.cancelTraining(id);await loadTraining()}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
function poll(){timer=setTimeout(async()=>{if(!document.hidden)await load();if(!controller.signal.aborted)poll()},5000)}
watch(status,()=>{page.value=0;void load()})
onMounted(()=>{void load();void loadTraining();poll()});onBeforeUnmount(()=>{controller.abort();clearTimeout(timer)})
</script>
<template><section><header class="research-section-title"><div><h2>{{ uiText('任务与同步') }}</h2><p class="research-hint">{{ uiText('文档任务在后台处理，关闭页面后可回来继续查看。导出完成表示服务器已生成内容，请确认浏览器保存成功。') }}</p></div><button class="button" @click="load();loadTraining()">{{ uiText('刷新') }}</button></header><label class="task-filter">{{uiText('任务范围')}}<select v-model="status" class="field-input"><option value="ALL">{{uiText('全部')}}</option><option value="ACTIVE">{{uiText('进行中')}}</option><option value="FAILED">{{uiText('需要重试')}}</option><option value="SUCCEEDED">{{uiText('已完成')}}</option></select></label><p v-if="error" class="form-error" role="alert">{{ uiText(error) }}</p><p v-if="!rows.length" class="research-empty">{{ uiText('暂无任务记录。') }}</p><article v-for="j in rows" :key="j.id" class="job-row"><div><strong>{{j.title}}</strong><p>{{new Date(j.createdAt).toLocaleString(uiLocale())}} · {{ uiText(names[j.status]||j.status) }}</p><progress v-if="['RUNNING','QUEUED','CANCELLING'].includes(j.status)" :value="j.progress" max="100"/><p v-if="j.message" class="research-hint">{{j.message}}</p></div><div class="research-actions"><RouterLink v-if="j.resultId" :to="'/app/research?tab=documents&document='+j.resultId">{{ uiText('打开文档 →') }}</RouterLink><button v-if="['RUNNING','QUEUED'].includes(j.status)&&j.kind.startsWith('DOCUMENT_')" class="button" :disabled="!!busy" @click="action(j,'cancel')">{{ uiText('取消') }}</button><button v-if="['FAILED','CANCELLED'].includes(j.status)&&j.kind.startsWith('DOCUMENT_')&&j.attempts<3" class="button" :disabled="!!busy" @click="action(j,'retry')">{{ uiText('重试') }}</button><button v-if="['SUCCEEDED','FAILED','CANCELLED'].includes(j.status)" class="table-action" @click="remove(j)">{{ uiText('移除记录') }}</button><RouterLink v-if="j.kind==='SYNC'" to="/offline">{{ uiText('查看离线同步 →') }}</RouterLink><RouterLink v-if="j.kind==='IMPORT'" to="/app/vocabulary">{{ uiText('返回词书 →') }}</RouterLink></div></article><nav class="research-pagination"><button class="button" :disabled="page===0" @click="page--;load()">{{ uiText('上一页') }}</button><span>{{page+1}}</span><button class="button" :disabled="rows.length<30" @click="page++;load()">{{ uiText('下一页') }}</button></nav><template v-if="authStore.has('training:use')"><h3>{{ uiText('本地训练') }}</h3><p v-if="trainingError" role="status">{{ uiText(trainingError) }}</p><article v-for="job in training" :key="job.id" class="job-row"><div><strong>{{job.name}}</strong><p>{{ uiText(names[job.status]||job.status) }}</p></div><button v-if="['QUEUED','RUNNING'].includes(job.status)" class="button" :disabled="!!busy" @click="cancelTraining(job.id)">{{ uiText('取消训练') }}</button></article><RouterLink to="/app/settings?section=ai">{{ uiText('查看训练详情 →') }}</RouterLink></template></section></template>
<style scoped>.job-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;border-bottom:1px solid var(--line)}.job-row strong{font-weight:500;overflow-wrap:anywhere}.job-row p{font-size:13px;color:var(--muted);margin:8px 0}.job-row progress{height:4px;width:240px;accent-color:var(--green)}</style>
